<section class="card"><div class="card-header"><div><h2>Timeline مشتری</h2><p class="text-muted">آخرین فعالیت‌های قرارداد، پرداخت، تماس، حقوقی و اتوماسیون</p></div></div><div class="card-body"><div class="proma-customer-360__timeline"><?php foreach (($timeline ?? []) as $item): ?><article><span class="proma-customer-360__timeline-dot is-<?= e($item['kind'] ?? 'system') ?>"></span><div><strong><?= e($item['title'] ?? 'فعالیت مشتری') ?></strong><p><?= e($item['description'] ?? '') ?></p><time><?= e(jdatetime($item['created_at'] ?? '')) ?></time></div><?php if (!empty($item['route'])): ?><a class="btn small secondary" href="<?= e(url($item['route'])) ?>">مشاهده</a><?php endif; ?></article><?php endforeach; ?><?php if (empty($timeline)): ?><div class="proma-empty-state"><p>فعالیتی برای نمایش ثبت نشده است.</p></div><?php endif; ?></div></div></section>
